INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-ise315', 'stk-bader_alqahtani', 'ISE 315', 'doc', '{"docs": [{"id": "stk-dr-f98636", "n": "Dr. Omar Al-Turki", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ise315-192\n\nالشرح: يشرح من سلايدات خاصه فيه و يركز على الكونسبت اكثر شي شرحه مقبول مش سيء تقدر تستفيد منه ولكن مش ١٠٠٪؜ يعني لو مركز معه بتقدر تطلع بفايدة و تسهل عليك مذاكرتك يعني من الكلاس راح تفهم من ٢٠الى ٣٥٪؜ من الدرس ،كان يحل لنا اسألة نهاية كل تشابتر لكن من حصل الاون لاين بطل يسويها.\n\nالتصحيح: تصحيحه وسط صراحة م يخسف فيك ولا يرفعك كثير وسط ممكن يعطيك حقك و زيادة شوي الا لو مرة حلك غلط م بيقدر يساعدك.\n\nالتعامل:الصراحة اخلاق و تعامله طيب مع الطلبة و لكن متقلب مزاج مرة فصل علينا اسبوعين اعتقد بعدها صار احسن .\n\nالتحضير: يحضر بعد بداية الحصة بخمس دقايق تقريبا و احيانا ١٠ اذا تاخرت بيحطك ليت .\n\nالكوزات:صراحة سهلة و اغلبها من اسألة الكتاب و دايم يركز على مدى فهم الطالب فيها .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521976-ise315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-omar-al-turki/98636/13", "user": "Bader_Alqahtani", "ts": 1589224126000, "tid": 98636, "pn": 13}}]}', 1589224126000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-doi-ise315', 'stk-doi', 'ISE 315', 'doc', '{"docs": [{"id": "stk-dr-f98636", "n": "Dr. Omar Al-Turki", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 315 - Term 212:\n\nالتحضير:\nكان ياخذ التحضير بالاسماء بعد بداية الكلاس بـ5 دقايق.\n\nطريقة الشرح:\nيشرح من السلايدات وأغلبها حشي كلام وكان يقول أفضل شى تذاكر بنفسك.\n\nالـQuizes:\nكويزاته كانت سهله الصدق وواضحه.\n\nالـMajors:\nعطانا ميجرين وكلها متوسطه مايله للصعوبه, الثاني كان فيه اغلاط كثير بكتابة الاسئلة وماكان يحب احد يناقشه او يقول له فيه أغلاط.\n\nالـFinal:\nالفاينل كان مو سهل للامانه, وفيه تريكات كثير.\n\nالقريد النهائي:\nC\n\nإضافات:\nالدكتور اتوقع اخر ترم له ترم 212 ويقال انه بيترك الجامعه, بس احتياطا قلت أكتب عنه بحيث لو مامشى يقدرون يستفيدون من المنتدى الشباب … وختامًا الدكتور يراعي الطلاب للامانه ما عنده مشكلة ياجل الاختبارات ويسوي تصويت للوقت المناسب للجميع.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535690-ise315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-omar-al-turki/98636/16", "user": "DOI", "ts": 1666894225000, "tid": 98636, "pn": 16}}]}', 1666894225000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zad-ise315', 'stk-zad', 'ISE 315', 'doc', '{"docs": [{"id": "stk-dr-f98655", "n": "Dr. M Dhurgham", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE315 T212\n\nالتحضير : نادر يحضر وعادة اذا كان فيه غياب بس\n\nالشرح : ممتاز جدا\n\nالكويزات: سهلة غالبا إلى متوسطة\nالمياجر: كومون\nالفاينلات: كومون\n\nالتصحيح: تصحيحه حقاني لكن ممكن يمشي لك شوية\n\nالصوت : واضح\n\nإضافات:\n- الدكتور حبيب جدا ومتعاون.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536501-ise315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-dhurgham/98655/34", "user": "ZAD", "ts": 1679079179000, "tid": 98655, "pn": 34}}]}', 1679079179000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abinmua-ise315', 'stk-abinmua', 'ISE 315', 'doc', '{"docs": [{"id": "stk-dr-f182616", "n": "Dr. Mohammad Nabhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 202 - ISE315\n\nالتحضير : يرسل فورم تحضير وتعبيه خلال مدة اقصاها عشر دقايق تقريبا\n\nطريقة الشرح : الدكتور يتضح عليه انه محضر بشكل ممتار للمحاضرة ، يبدا بكتابة النوتس بالايباد وطريقته بترتيب النوتس والتلخيص ممتازة جداً وتختصر على الطالب الكثير ، ميزة الدكتور عند بداية كل محاضرة يرجع يراجع ماسبق ويخليك تسترجع المعلومة بشكل جيد ، بطيء نوعا ما بالشرح وممكن تمل لكن لو تركز راح تفهم\n\nالكويزات : كانت سهلة الى متوسطة ، ذاكر نوتاته وافهم كونسبت الكتاب وحل الهومورك وماراح تشوف الكويز شي\n\nالمياجر : قسم المادة الى ٢ ميد تيرم واحد عليه ١٥ وواحد ٢٢.٥ ، اثنينها كانت متوسطة برايي ومايلة للسهولة للي تعلم يستخدم اكسل او ماتلاب بالمد الثاني\n\nالفاينل : الفاينل للامانة كان صعب جداً وطريقة بعض الاسئلة كانت جديدة وتلحس شوي ومليان تركات\n\nالقريد النهائي : A\n\nالدكتور يعطي بارشل على الحل وكريم فيه بعد ومتعاون جداً مع الطلاب بالاوفس اور مستعد مايطلع الا وانت فاهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531296-ise315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-nabhan/182616/5", "user": "AbinMua", "ts": 1629138988000, "tid": 182616, "pn": 5}}]}', 1629138988000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-ise315', 'stk-user12137', 'ISE 315', 'doc', '{"docs": [{"id": "stk-dr-f182616", "n": "Dr. Mohammad Nabhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE315 - term232\n\nالتحضير :\nتحضير بشكل يومي بعد البدء ب4 دقائق, وما يعطي تأخير أبدا, أهم شيء تجيه نهاية الكلاس وتنبهه وما تكون دائما تتأخر لأنه يحفظ الطلاب بسرعة؛ فممكن ما يرضى\n\nطريقة الشرح :\nالدكتور شرحه واضح جدا, وشرحه كله على الآيباد وهو واقف يكتب, ويعرف حقا كيف يشرح على الآيباد محلله تحليل, وطريقته يبدأ بما ناقشناه الكلاس الي فات, ثم يبدأ يشرح, ويوقف بعد كل نقطة ويسأل سؤاله المفضل “?Does it make sense” بتسمعها ألف مرة بالسمتستر ويعجبني هالسؤال والله, ولا في سلايدات ولا شيء, بس يجي ويكتب على الآيباد وزي ما ذكروا الي فوقي, التلخيص ممتاز جداً, ونصيحتي أطلبوا منه يرفع النوتس الي كتبها في الكلاس على البلاكبورد\n\nالكويزات :\nلا يوجد\nفقط هوموركات\n\nالمياجر:\nمستواها سهل جدا\n\nالفاينلات :\nمستواه سهل جدا\nأسمع إذا الضرغام ماسك المادة تجيك شق وصعبة, لكن إذا النبهان ماسكها فالمادة تجيك خفيفة\n\nالقريد النهائي:\nA+\n\nالصوت:\nرايق\n\nإضافات :\n-الدكتور خوش رجال أخلاق ومتساعد, وحتى يقعد معنا بعد الكلاس لفترة طويلة يشرح لنا المفاهيم أو المواضيع الخارجية الي ما فهمناها, وتحسه فاهم بالبرمجة بعد\n-أشوفه أفضل دكتور ممكن تنزل عنده 315 أو أي مادة بشكل عام, لأنه محضر بشكل ممتاز جدا؛ فصعب تطلع منها وأنت مو فاهم\n-ومن النوع الي إذا تنكت معاه يفهم عليك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537323-ise315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-nabhan/182616/7", "user": "user12137", "ts": 1716989832000, "tid": 182616, "pn": 7}}]}', 1716989832000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
